import{z as A,x as d,o as r,c as p,q as o,j as s,D as n,d as E,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"密码学误用清单","description":"","frontmatter":{"title":"密码学误用清单","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/crypto-misuse.md","filePath":"cs/crypto-misuse.md","lastUpdated":1791413859000}'),B={name:"cs/crypto-misuse.md"};function c(m,a,u,C,h,D){const t=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="密码学误用清单" tabindex="-1">密码学误用清单 <a class="header-anchor" href="#密码学误用清单" aria-label="Permalink to &quot;密码学误用清单&quot;">​</a></h1><div class="epigraph"><p>破掉产品的常常不是新的密码分析，而是 ECB、nonce 复用、裸哈希当 MAC、自制 RNG、把身份写进 JWT 却不验签。清单用来对照合同，不是利用手册。</p><footer>—— 据 Anderson, *Security Engineering*；Egele et al. 对 Android 密码学误用的测量；对照 NIST 与 RFC 的合同条款</footer></div><p>上一课<a href="/cs/provable-security-reduction">归约</a>说明证明有前提。缺口是把本单元散见的失败收成<strong>检查单</strong>，作为密码学进阶的封口，并交给下一单元「证书链到底验什么」。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工程上重复出现：ECB 或未认证加密、静态 IV、CBC+可区分填充错误、\\(H(k\\|m)\\)、MD5 当签名哈希、RSA 无填充、ECDSA 坏 \\(k\\)、硬编码密钥、自签还关校验。缺口是清单与「每条对应哪一课合同」，不是新算法。</p><h3 id="库默认值也是合同" tabindex="-1">库默认值也是合同 <a class="header-anchor" href="#库默认值也是合同" aria-label="Permalink to &quot;库默认值也是合同&quot;">​</a></h3><p>有的 API 默认 ECB 或允许 <code>None</code> 算法。选库等于选游戏前提。</p><p><span class="marginnote">Anderson 反复强调实现与流程。学术测量（如 CryptoLint 一类）表明误用普遍。本课不提供扫描目标站点的操作指南。</span></p><p><span class="marginnote">术语翻译：「游戏前提」是归约证明里的那套规则——攻击者拿到的输入、能问的问题都被约定好。误用等于把规则改了还沿用旧证明：证明只在合同内有效，出了合同什么都没保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按原语课序对照列出「正确形状」。要求：AEAD、唯一 nonce、HMAC/HKDF、OAEP/PSS、CSPRNG、密钥分离、常数时间比较。指出下一单元从 PKI 验证细节开始，因为「有证书」仍可能什么都没验。</p>',12)),(r(),s(i,null,{default:n(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E9%80%89%E9%94%99%E6%A8%A1%E5%BC%8F%2Fnonce%22%5D%20--%3E%20FAIL%5B%22%E6%B8%B8%E6%88%8F%E5%89%8D%E6%8F%90%E7%A0%B4%22%5D%0A%20%20L2%5B%22%E8%A3%B8%E5%93%88%E5%B8%8C%E5%BD%93%E8%AE%A4%E8%AF%81%22%5D%20--%3E%20FAIL%0A%20%20L3%5B%22%E5%9D%8F%20RNG%20%2F%20%E5%AF%86%E9%92%A5%E7%A1%AC%E7%BC%96%E7%A0%81%22%5D%20--%3E%20FAIL%0A%20%20FAIL%20--%3E%20FIX%5B%22%E5%9B%9E%E5%88%B0%20AEAD%20%E4%B8%8E%20HKDF%20%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：AES-GCM 的 nonce 是 96 位，同一密钥下只要重用一次，认证密钥就可能被恢复、任意密文可被伪造。nonce 不需要保密，但在同一密钥下绝不能重复——「唯一」比「随机」更重要。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("误用把可证明对象变回「有加密外观」。审查应问合同而非算法名。协议与身份单元将看到：TLS 配置、JWT "),e("code",null,"alg"),E("、OAuth 重定向，是同一类失败在协议层的投影。")],-1)),(r(),s(i,null,{default:n(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E6%98%8E%E6%96%87%E5%90%AB%E4%B8%A4%E5%9D%97%E7%9B%B8%E5%90%8C%E5%86%85%E5%AE%B9%22%5D%20--%3E%20ECB%5B%22ECB%3A%20%E5%90%84%E5%9D%97%E7%8B%AC%E7%AB%8B%E5%8A%A0%E5%AF%86%22%5D%0A%20%20ECB%20--%3E%20CT%5B%22%E4%B8%A4%E5%9D%97%E5%AF%86%E6%96%87%E4%B9%9F%E7%9B%B8%E5%90%8C%2C%20%E5%9B%BE%E6%A1%88%E5%8F%AF%E8%A7%81%22%5D%0A%20%20PT%20--%3E%20AE%5B%22AEAD%3A%20%E5%94%AF%E4%B8%80%20nonce%20%E5%8F%82%E4%B8%8E%E6%AF%8F%E4%B8%80%E5%9D%97%22%5D%0A%20%20AE%20--%3E%20CT2%5B%22%E7%9B%B8%E5%90%8C%E6%98%8E%E6%96%87%E5%BE%97%E5%87%BA%E4%B8%8D%E5%90%8C%E5%AF%86%E6%96%87%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：初学者容易以为「用了 AES 就安全了」。算法名只说明原语本身；模式、nonce、填充、密钥来源任何一环用错，都会把它变回「有加密外观的明文」——所以审查要问合同，不是问算法名。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把清单写成攻击脚本。下一课程单元「协议与身份」第一课：证书链验证细节——主干 PKI 课之后仍被跳过的那些检查。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归约在合同内；本课列合同外高频失败。</li><li>AEAD、nonce、HMAC、填充、RNG、密钥分离。</li><li>库默认与「有加密」不是证明。</li><li>下一单元：证书链验证细节。</li><li>出处：Anderson, <em>Security Engineering</em>；Egele et al.；NIST SP 800-38 系列与 RFC 8446。</li></ul>',5))])}const f=A(B,[["render",c]]);export{T as __pageData,f as default};
